#include <algorithm>
#include <array>
#include <cmath>
#include <iostream>
#include <numeric>
using namespace std;
using i64 = long long;
using i128 = __int128_t;
constexpr i64 MOD = 998244353;

i64 residue(i128 x, i64 m) {
    x %= m;
    if (x < 0) x += m;
    return static_cast<i64>(x);
}
i64 inverse(i64 a, i64 m) {
    if (m == 1) return 0;
    i128 x0 = 1, x1 = 0;
    i64 b = m;
    while (b) {
        i64 q = a / b;
        i64 r = a % b;
        a = b; b = r;
        i128 x2 = x0 - static_cast<i128>(q) * x1;
        x0 = x1; x1 = x2;
    }
    return residue(x0, m);
}

struct Congruence {
    i64 divisor, period, inv;
    Congruence(i64 coefficient, i64 modulus) {
        divisor = gcd(coefficient, modulus);
        period = modulus / divisor;
        inv = inverse(coefficient / divisor, period);
    }
    i64 first(i128 rhs) const {
        if (rhs % divisor != 0) return -1;
        return residue((rhs / divisor) * inv, period);
    }
    i64 count(i128 rhs, i64 length) const {
        i64 x = first(rhs);
        return x < 0 || x >= length ? 0 : (length - 1 - x) / period + 1;
    }
};

i128 floor_sum(i64 n, i64 m, i64 a, i64 b) {
    i128 answer = 0;
    while (true) {
        if (a >= m) {
            answer += static_cast<i128>(n) * (n - 1) / 2 * (a / m);
            a %= m;
        }
        if (b >= m) {
            answer += static_cast<i128>(n) * (b / m);
            b %= m;
        }
        i128 top = static_cast<i128>(a) * n + b;
        if (top < m) return answer;
        n = static_cast<i64>(top / m);
        b = static_cast<i64>(top % m);
        swap(m, a);
    }
}

i64 count_ge(i64 length, i64 m, i64 a, i64 b, i64 threshold,
             bool zero_is_modulus, const Congruence &zero_solver) {
    if (threshold <= 0) return length;
    if (threshold > m) return 0;
    if (length <= 1) {
        if (!length) return 0;
        i64 value = b == 0 && zero_is_modulus ? m : b;
        return value >= threshold;
    }
    i128 answer = floor_sum(length, m, a, b + m - threshold)
                - floor_sum(length, m, a, b);
    if (zero_is_modulus) answer += zero_solver.count(-static_cast<i128>(b), length);
    return static_cast<i64>(answer);
}
i64 triangular_gap(i64 distance) {
    i128 d = distance;
    return static_cast<i64>((d * (d - 1) / 2) % MOD);
}
i64 merge_direct(i64 n, const array<i64, 3> &a, const array<i64, 3> &b) {
    array<i64, 3> next = b;
    i64 last = -1, answer = 0;
    while (true) {
        i64 x = *min_element(next.begin(), next.end());
        if (x >= n) break;
        answer = (answer + triangular_gap(x - last)) % MOD;
        last = x;
        for (int i = 0; i < 3; ++i) if (next[i] == x) next[i] += a[i];
    }
    return (answer + triangular_gap(n - last)) % MOD;
}
i64 solve(i64 n, const array<i64, 3> &a, const array<i64, 3> &b,
          int forced_mode = -1) {
    i64 cap = *min_element(a.begin(), a.end());
    i64 threshold = max<i64>(1, sqrt(static_cast<long double>(n) / max<long double>(1, log2(n + 1))));
    if (forced_mode == 0 || (forced_mode == -1 && cap > threshold))
        return merge_direct(n, a, b);
    i64 answer = 0, first_black = n, last_black = -1;
    int last_source = -1;
    i64 baseline = triangular_gap(cap);
    for (int p = 0; p < 3; ++p) {
        if (b[p] >= n) continue;
        first_black = min(first_black, b[p]);
        i64 length = (n - 1 - b[p]) / a[p] + 1;
        i64 last = b[p] + (length - 1) * a[p];
        if (last > last_black || (last == last_black && p > last_source))
            last_black = last, last_source = p;
        answer = residue(answer + static_cast<i128>(length % MOD) * baseline, MOD);
        int i = (p + 1) % 3, j = (p + 2) % 3;

        for (int orientation = 0; orientation < 2; ++orientation) {
            int event = orientation ? j : i;
            int other = orientation ? i : j;
            Congruence event_solver(a[p], a[event]);
            i64 step = event_solver.period;
            i64 other_a = residue(-static_cast<i128>(a[p]) * step, a[other]);
            Congruence zero_solver(other_a, a[other]);
            for (i64 value = 0; value < cap; ++value) {
                if (value == 0 && event < p) continue;
                i64 k0 = event_solver.first(static_cast<i128>(b[event]) - b[p] - value);
                if (k0 < 0 || k0 >= length) continue;
                i64 count = (length - 1 - k0) / step + 1;
                i64 other_b = residue(static_cast<i128>(b[other]) - b[p]
                                     - static_cast<i128>(a[p]) * k0, a[other]);
                i64 accepted = count_ge(count, a[other], other_a, other_b,
                                        value + orientation, other < p, zero_solver);
                i64 delta = triangular_gap(value) - baseline;
                answer = residue(answer + static_cast<i128>(accepted % MOD) * delta, MOD);
            }
        }
    }
    if (last_black < 0) return triangular_gap(n + 1);
    answer = residue(answer + triangular_gap(first_black + 1), MOD);
    i64 infinite_gap = a[last_source];
    for (int i = 0; i < 3; ++i) if (i != last_source) {
        i64 d = residue(static_cast<i128>(b[i]) - last_black, a[i]);
        if (d == 0 && i < last_source) d = a[i];
        infinite_gap = min(infinite_gap, d);
    }
    return residue(answer - triangular_gap(infinite_gap) + triangular_gap(n - last_black), MOD);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    i64 n;
    array<i64, 3> a, b;
    if (!(cin >> n)) return 0;
    for (int i = 0; i < 3; ++i) cin >> a[i] >> b[i];
    cout << solve(n, a, b) << '\n';
    return 0;
}
